    "bibleContext": "Justo después de que Pedro confesara que Jesús es el Cristo, Jesús comienza a hablar abiertamente sobre su propia muerte y llama a sus discípulos a un tipo de seguimiento radical: negarse a sí mismo, tomar su cruz cada día y seguirlo. En ese contexto histórico, cargar una cruz significaba caminar hacia la propia ejecución; no era una metáfora suave sino una imagen impactante de rendición total. Jesús enseña que quien intente salvar su vida aferrándose a sus propios planes la perderá, pero quien la pierda por causa de Él la salvará verdaderamente. También advierte sobre el peligro de avergonzarse de Él y de sus palabras. Este pasaje deja claro que el discipulado cristiano no es una decisión cómoda ni superficial, sino un compromiso diario que reordena las prioridades de toda la vida.",
