    "bibleContext": "Isaías 53 describe con gran detalle, siglos antes de que ocurriera, el sufrimiento de un Siervo que sería \"herido por nuestras rebeliones\" y \"molido por nuestros pecados\", cargando un castigo que no era el suyo para traer paz y sanidad a otros. El texto es explícito en su lenguaje sustitutorio: \"Jehová cargó en él el pecado de todos nosotros\". Pedro, siglos después, cita directamente este pasaje en su primera carta para explicar la muerte de Jesús: \"quien llevó él mismo nuestros pecados en su cuerpo sobre el madero\". La cruz, entonces, no fue un accidente trágico ni solo un ejemplo de amor sacrificial; fue el cumplimiento planeado de la justicia de Dios, donde Jesús, sin pecado, tomó el lugar de los culpables para que ellos pudieran recibir el perdón y la paz con Dios.",
